package nettest

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"fmt"
	"math/big"
	"net"
	"os"
	"path/filepath"
	"testing"
	"time"
)

// CertOptions configures a certificate generated by GenCert.
type CertOptions struct {
	// CN is the certificate subject common name.
	CN string
	// Hosts are the subject alternative names. Each entry is added as an IP
	// SAN when it parses as an IP address, otherwise as a DNS SAN. Empty
	// entries are skipped.
	Hosts []string
	// NotBefore and NotAfter bound the validity period.
	NotBefore time.Time
	NotAfter  time.Time
	// ExtKeyUsages sets the extended key usages (e.g. serverAuth, clientAuth).
	ExtKeyUsages []x509.ExtKeyUsage
	// SignerCert and SignerKey sign the certificate. When either is nil the
	// certificate is self-signed and marked as a CA.
	SignerCert *x509.Certificate
	SignerKey  *ecdsa.PrivateKey
}

// GenCert generates an ECDSA P-256 certificate from opts. When no signer is
// provided the certificate is self-signed and marked as a CA. It returns the
// PEM-encoded certificate and key together with the parsed certificate and its
// private key, so the result can in turn sign further certificates. Any error
// fails the test.
func MustGenCert(t testing.TB, opts CertOptions) (certPEM, keyPEM []byte, cert *x509.Certificate, key *ecdsa.PrivateKey) {
	t.Helper()
	certPEM, keyPEM, cert, key, err := GenCert(opts)
	if err != nil {
		t.Fatalf("nettest: %v", err)
	}
	return
}

// GenCertErr is the testing.TB-free variant of GenCert for callers without a
// test handle (e.g. helpers that panic). Prefer GenCert in tests.
func GenCert(opts CertOptions) (certPEM, keyPEM []byte, cert *x509.Certificate, key *ecdsa.PrivateKey, err error) {
	key, err = ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("failed to generate key: %w", err)
	}

	tmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(time.Now().UnixNano()),
		Subject:               pkix.Name{CommonName: opts.CN},
		NotBefore:             opts.NotBefore,
		NotAfter:              opts.NotAfter,
		KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageKeyEncipherment,
		ExtKeyUsage:           opts.ExtKeyUsages,
		BasicConstraintsValid: true,
	}
	for _, h := range opts.Hosts {
		if h == "" {
			continue
		}
		if ip := net.ParseIP(h); ip != nil {
			tmpl.IPAddresses = append(tmpl.IPAddresses, ip)
		} else {
			tmpl.DNSNames = append(tmpl.DNSNames, h)
		}
	}

	parent, parentKey := tmpl, key
	if opts.SignerCert != nil && opts.SignerKey != nil {
		parent, parentKey = opts.SignerCert, opts.SignerKey
	} else {
		tmpl.IsCA = true
		tmpl.KeyUsage |= x509.KeyUsageCertSign
	}

	der, err := x509.CreateCertificate(rand.Reader, tmpl, parent, &key.PublicKey, parentKey)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("failed to create certificate: %w", err)
	}
	cert, err = x509.ParseCertificate(der)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("failed to parse certificate: %w", err)
	}

	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, nil, nil, fmt.Errorf("failed to marshal key: %w", err)
	}
	certPEM = pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
	keyPEM = pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})
	return certPEM, keyPEM, cert, key, nil
}

// CA is a generated certificate authority able to sign server and client
// certificates for tests.
type CA struct {
	Cert    *x509.Certificate
	Key     *ecdsa.PrivateKey
	CertPEM []byte
}

// NewCA generates a self-signed CA valid for 24 hours.
func NewCA(t testing.TB) *CA {
	t.Helper()
	now := time.Now()
	certPEM, _, cert, key := MustGenCert(t, CertOptions{
		CN:        "nettest-ca",
		NotBefore: now.Add(-1 * time.Hour),
		NotAfter:  now.Add(24 * time.Hour),
	})
	return &CA{Cert: cert, Key: key, CertPEM: certPEM}
}

// ServerCert returns a CA-signed server certificate (serverAuth) whose SANs are
// hosts, defaulting to 127.0.0.1 when none are given. The result is PEM-encoded.
func (ca *CA) ServerCert(t testing.TB, hosts ...string) (certPEM, keyPEM []byte) {
	t.Helper()
	if len(hosts) == 0 {
		hosts = []string{"127.0.0.1"}
	}
	now := time.Now()
	certPEM, keyPEM, _, _ = MustGenCert(t, CertOptions{
		CN:           "nettest-server",
		Hosts:        hosts,
		NotBefore:    now.Add(-1 * time.Hour),
		NotAfter:     now.Add(24 * time.Hour),
		ExtKeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		SignerCert:   ca.Cert,
		SignerKey:    ca.Key,
	})
	return
}

// ClientCert returns a CA-signed client certificate (clientAuth), PEM-encoded.
func (ca *CA) ClientCert(t testing.TB) (certPEM, keyPEM []byte) {
	t.Helper()
	now := time.Now()
	certPEM, keyPEM, _, _ = MustGenCert(t, CertOptions{
		CN:           "nettest-client",
		NotBefore:    now.Add(-1 * time.Hour),
		NotAfter:     now.Add(24 * time.Hour),
		ExtKeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
		SignerCert:   ca.Cert,
		SignerKey:    ca.Key,
	})
	return
}

// WriteCertKey writes certPEM and keyPEM to files in a per-call temp directory
// that is removed when the test finishes, returning their paths.
func WriteCertKey(t testing.TB, certPEM, keyPEM []byte) (certFile, keyFile string) {
	t.Helper()
	dir := t.TempDir()
	certFile = filepath.Join(dir, "cert.pem")
	keyFile = filepath.Join(dir, "key.pem")
	if err := os.WriteFile(certFile, certPEM, 0644); err != nil {
		t.Fatalf("nettest: failed to write cert file: %v", err)
	}
	if err := os.WriteFile(keyFile, keyPEM, 0600); err != nil {
		t.Fatalf("nettest: failed to write key file: %v", err)
	}
	return
}
